// A few types of the stripe package, installed inside the scanned directory: a scan reads no package from above it.
declare namespace Stripe {
  type LatestApiVersion = "2024-06-20";

  interface StripeConfig {
    apiVersion?: LatestApiVersion;
  }

  interface AddressParam {
    city?: string;
    country?: string;
    line1?: string;
    postal_code?: string;
  }

  interface CustomerCreateParams {
    address?: AddressParam | "";
    balance?: number;
    description?: string;
    email?: string;
    metadata?: Record<string, string> | "";
    name?: string;
  }

  interface SubscriptionUpdateParams {
    cancel_at_period_end?: boolean;
    default_payment_method?: string;
    metadata?: Record<string, string> | "";
    proration_behavior?: "always_invoice" | "create_prorations" | "none";
  }

  interface Resource {
    create(params?: object): Promise<object>;
    retrieve(id?: string): Promise<object>;
    update(id: string, params?: object): Promise<object>;
  }
}

declare class Stripe {
  constructor(apiKey: string, config?: Stripe.StripeConfig);
  balance: Stripe.Resource;
  checkout: { sessions: Stripe.Resource };
  customers: { create(params?: Stripe.CustomerCreateParams): Promise<object> };
  paymentIntents: Stripe.Resource;
  subscriptions: { update(id: string, params?: Stripe.SubscriptionUpdateParams): Promise<object> };
}

export = Stripe;
